1	// Drives the app through its screens, binding only to data-testid (AGENTS.md §2). Every test
2	// arranges its own data with these helpers and asserts through them or through data-testid
3	// directly. An action helper returns what the screen reported: an id when a row was created,
4	// true/false for whether the action went through or the screen refused it (its error element
5	// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
6	// does nothing fails the test instead of passing as "refused".
7	import { expect, test, type Browser, type BrowserContext, type Locator, type Page } from '@playwright/test';
8	import { existsSync, readFileSync } from 'node:fs';
9	
10	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
11	const WAIT = 8000;
12	const LOAD_WAIT = 30000;      // a sign-in, a sheet load or a today change: the whole sheet is re-read
13	const ERROR_GRACE = 2000;     // how long an error left over from the action before may linger
14	const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen
15	
16	const editing = new WeakMap<Page, string>();
17	
18	export function sheetId(): string {
19	  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
20	}
21	
22	/** The id a creating helper returned; throws when the screen refused (null) so the failure
23	 *  lands on the arranging line rather than on a later assertion. */
24	export function must(id: string | null): string {
25	  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
26	  return id;
27	}
28	
29	function escapeRe(s: string): string {
30	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
31	}
32	
33	/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
34	 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
35	 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
36	async function shown(loc: Locator): Promise<string> {
37	  return ((await loc.allTextContents())[0] ?? '').trim();
38	}
39	
40	/** The ids carried by every element matching `loc`, read without waiting. */
41	async function ids(loc: Locator, prefix: string): Promise<string[]> {
42	  const out: string[] = [];
43	  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
44	  return out;
45	}
46	
47	/** The rows matching `loc` whose id is not in `before`, in screen order, each with its id and the
48	 *  text of the named cells; read without waiting, so a poll may call it. A creating helper finds
49	 *  its row this way: a page may be showing the sheet as it was when it was loaded, so the rows
50	 *  other users added can land on it at any moment, including between a submit and its result. */
51	async function freshRows(loc: Locator, prefix: string, before: string[], cells: string[]): Promise<Record<string, string>[]> {
52	  const out: Record<string, string>[] = [];
53	  try {
54	    for (const h of await loc.elementHandles()) {
55	      const testid = (await h.getAttribute('data-testid')) ?? '';
56	      if (!testid.startsWith(prefix) || before.includes(testid.slice(prefix.length))) continue;
57	      const x: Record<string, string> = { id: testid.slice(prefix.length) };
58	      for (const c of cells) x[c] = ((await (await h.$(`[data-testid="${c}"]`))?.textContent()) ?? '').trim();
59	      out.push(x);
60	    }
61	  } catch {
62	    return [];                            // a row was re-rendered mid-read: the poll looks again
63	  }
64	  return out;
65	}
66	
67	/** An amount as the screen shows it: two decimals, a dot, no grouping. */
68	function money(amount: string): string {
69	  const n = Number(amount.trim());
70	  return amount.trim() !== '' && Number.isFinite(n) ? n.toFixed(2) : amount;
71	}
72	
73	/** A name as a name cell shows it, without a trailing " (<grade>)" the screen may append. */
74	function plainName(shown: string): string {
75	  return shown.trim().replace(/\s\([^()]*\)$/, '');
76	}
77	
78	/** The id of a person row new since `before` whose name is `name` (case and outer spaces
79	 *  ignored), or null when none shows yet. */
80	async function addedPerson(page: Page, before: string[], name: string): Promise<string | null> {
81	  const want = name.trim().toLowerCase();
82	  const hit = (await freshRows(rows(page), 'person-row-', before, ['person-name'])).find((p) => plainName(p['person-name']).toLowerCase() === want);
83	  return hit ? hit.id : null;
84	}
85	
86	/** The id of a claim row under `scope` new since `before` showing the amount (and the date,
87	 *  when one was given) that was entered, or null when none shows yet; the first in screen order
88	 *  (newest first) when more than one does. */
89	async function addedClaim(scope: Locator, before: string[], f: ClaimFields): Promise<string | null> {
90	  const want = money(f.amount ?? '');
91	  const hit = (await freshRows(claimRows(scope), 'claim-row-', before, ['claim-amount', 'claim-date']))
92	    .find((c) => c['claim-amount'] === want && (f.date === undefined || c['claim-date'] === f.date));
93	  return hit ? hit.id : null;
94	}
95	
96	/** The id of the first claim row under `scope` new since `before`, or null when none shows yet. */
97	async function addedAnyClaim(scope: Locator, before: string[]): Promise<string | null> {
98	  const hit = (await freshRows(claimRows(scope), 'claim-row-', before, []))[0];
99	  return hit ? hit.id : null;
100	}
