107	/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens.
108	 *  Each check returns as soon as it can. An error already visible at the first look after the
109	 *  click may be left over from the action before (the screen clears it when a new action is
110	 *  submitted, see README): it counts as this action's refusal once it has gone away and been
111	 *  shown again, once its text changes, or once ERROR_GRACE has passed with no result.
112	 *  `already` says `done` held BEFORE the action (watching a person already watched, saving a
113	 *  setting at its current value): then the result on screen proves nothing, and the action
114	 *  counts as taken only once ERROR_GRACE has passed with no refusal shown. */
115	async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string,
116	                     already = false): Promise<boolean> {
117	  const deadline = Date.now() + WAIT;
118	  let stale: string | null | undefined;   // text of an error visible at the first look; null if none
119	  let seenGone = false;
120	  const grace = Date.now() + ERROR_GRACE;
121	  while (Date.now() < deadline) {
122	    if (!already && await done()) return true;
123	    const visible = await error.isVisible().catch(() => false);
124	    if (stale === undefined) stale = visible ? await shown(error) : null;
125	    if (visible) {
126	      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
127	    } else {
128	      seenGone = true;
129	    }
130	    // the state held before the action: an error still showing at the grace outranks it
131	    if (already && Date.now() >= grace && await done()) return true;
132	    await page.waitForTimeout(50);
133	  }
134	  if (await done()) return true;
135	  if (await error.isVisible().catch(() => false)) return false;
136	  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
137	}
