794	/** Submit the open claim editor with `f` and judge the outcome. When the typed values are what the
795	 *  row already shows, the save cannot be seen on the row: the step then counts as saved only once
796	 *  no error has shown for a while (the `already` rule of until()). */
797	async function saveClaimEditor(page: Page, c: Locator, r: Locator, f: ClaimFields, what: string): Promise<boolean> {
798	  await fillClaimForm(r, f);
799	  const error = c.getByTestId('claim-error').or(r.getByTestId('claim-form-error'));
800	  const was = await editedCells(c, f);
801	  const already = await editedShows(c, f, was);
802	  await r.getByTestId('claim-form-submit').click();
803	  return until(page, async () => editedShows(c, f, was), error, what, already);
804	}
