813	/** The cells an edit will be judged by, as they are before the save. */
814	async function editedCells(c: Locator, f: ClaimFields): Promise<Record<string, string>> {
815	  const out: Record<string, string> = {};
816	  for (const k of Object.keys(f)) out[k] = await shown(c.getByTestId(`claim-${k}`));
817	  return out;
818	}
