820	/** Whether the row shows the edit: an amount, date, note or corrects cell equal to what was
821	 *  typed; a ref or tags cell, which the app normalises, is taken as saved once the form's error
822	 *  is not showing and the cell is no longer what it was (or the typed value, normalised, is a
823	 *  value it could not have had before). */
824	async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
825	  for (const [k, v] of Object.entries(f)) {
826	    const cell = await shown(c.getByTestId(`claim-${k}`));
827	    if (k === 'ref' || k === 'tags') {
828	      const norm = k === 'ref' ? v.trim() : v.split(',').map((t) => t.trim().toLowerCase()).filter((t) => t)
829	        .filter((t, i, a) => a.indexOf(t) === i).sort().join(', ');
830	      if (cell !== norm) return false;
831	    } else if (cell !== v) return false;
832	  }
833	  return true;
834	}
